def reinitializePermutation(n: int) -> int:
    # We track the index 1; index 0 never moves.
    pos = 1
    steps = 0
    while True:
        steps += 1
        if pos % 2 == 0:
            pos = pos // 2
        else:
            pos = n // 2 + (pos - 1) // 2
        if pos == 1:
            break
    return steps
